PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS controls (id INTEGER PRIMARY KEY CHECK(id=1), kill INTEGER NOT NULL CHECK(kill IN(0,1)), threshold REAL NOT NULL CHECK(threshold>=0 AND threshold<=1), threshold_justification TEXT NOT NULL);
INSERT OR IGNORE INTO controls(id,kill,threshold,threshold_justification) VALUES(1,0,0.90,'initial_design_threshold');
CREATE TABLE IF NOT EXISTS probes (id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotes (id TEXT PRIMARY KEY, actor TEXT NOT NULL, created_at TEXT NOT NULL, mode TEXT NOT NULL, type_version TEXT NOT NULL, pack_hash TEXT NOT NULL, request_json TEXT NOT NULL, estimate_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, actor TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('uploading','running','complete','halted','closing','closed')), created_at TEXT NOT NULL, closed_at TEXT, mode TEXT NOT NULL CHECK(mode IN('interactive','batch')), expected_count INTEGER NOT NULL, threshold REAL NOT NULL, threshold_justification TEXT NOT NULL, type_version TEXT NOT NULL, pack_json TEXT NOT NULL, budget_json TEXT NOT NULL, quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id), text_held INTEGER NOT NULL DEFAULT 1 CHECK(text_held IN(0,1)), manifest_key TEXT, halt_json TEXT, batch_leader TEXT);
CREATE TABLE IF NOT EXISTS documents (run_id TEXT NOT NULL REFERENCES runs(id), fingerprint TEXT NOT NULL, tag TEXT NOT NULL, original_filename TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('uploaded','running','complete')), input_key TEXT, input_hash TEXT NOT NULL, extractor_version TEXT, workflow_id TEXT, digest_key TEXT, confidence_key TEXT, reader_key TEXT, notes_json TEXT NOT NULL DEFAULT '[]', decision_json TEXT, failure_json TEXT, PRIMARY KEY(run_id,fingerprint), UNIQUE(run_id,tag));
CREATE TABLE IF NOT EXISTS artifacts (key TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), fingerprint TEXT, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'writing' CHECK(state IN('writing','complete')), contains_text INTEGER NOT NULL DEFAULT 0 CHECK(contains_text IN(0,1)), created_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), fingerprint TEXT, created_at TEXT NOT NULL, stage TEXT NOT NULL, kind TEXT NOT NULL, elapsed_ms INTEGER, details_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_run ON events(run_id,created_at);
CREATE TABLE IF NOT EXISTS checkpoints (run_id TEXT NOT NULL REFERENCES runs(id), fingerprint TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('running','complete','failed')), artifact_key TEXT, error_code TEXT, error_kind TEXT, error_detail TEXT, started_at TEXT NOT NULL, finished_at TEXT, PRIMARY KEY(run_id,fingerprint,name));
CREATE TABLE IF NOT EXISTS vendor_calls (attempt_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), fingerprint TEXT NOT NULL, role TEXT NOT NULL, model_requested TEXT NOT NULL, model_returned TEXT, status INTEGER, latency_ms INTEGER NOT NULL, request_id TEXT, usage_json TEXT, cost_nano TEXT, raw_key TEXT NOT NULL REFERENCES artifacts(key), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS vendor_calls_run ON vendor_calls(run_id);
CREATE TABLE IF NOT EXISTS vendor_circuits (run_id TEXT NOT NULL REFERENCES runs(id), vendor TEXT NOT NULL, failures INTEGER NOT NULL, PRIMARY KEY(run_id,vendor));
CREATE TABLE IF NOT EXISTS corrections (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), actor TEXT NOT NULL, created_at TEXT NOT NULL, raw_key TEXT NOT NULL REFERENCES artifacts(key), result_key TEXT NOT NULL REFERENCES artifacts(key), proposals_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS threshold_history (id TEXT PRIMARY KEY, correction_id TEXT NOT NULL REFERENCES corrections(id), actor TEXT NOT NULL, created_at TEXT NOT NULL, threshold REAL NOT NULL, direction TEXT NOT NULL, UNIQUE(correction_id,direction));
CREATE TABLE IF NOT EXISTS batch_jobs (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), fingerprint TEXT NOT NULL, schema_attempt INTEGER NOT NULL, state TEXT NOT NULL, input_file_id TEXT, remote_batch_id TEXT, result_key TEXT, UNIQUE(run_id,fingerprint,schema_attempt));
CREATE TABLE IF NOT EXISTS batch_requests (run_id TEXT NOT NULL REFERENCES runs(id), fingerprint TEXT NOT NULL, request_key TEXT NOT NULL REFERENCES artifacts(key), PRIMARY KEY(run_id,fingerprint));